import re
import os
from pathlib import Path
import glob

def task_func(directory_path: str, regex_pattern: str = r'\(.+?\)|\w') -> dict:
    """
    Extract matches from all files in a directory using the provided regex.

    Returns:
        dict: {filename_without_path: [matched_strings, ...], ...}
    """
    directory = Path(directory_path)
    if not directory.exists() or not directory.is_dir():
        return {}

    try:
        pattern = re.compile(regex_pattern)
    except re.error:
        # Propagate invalid regex errors in a standard way
        raise

    results = {}

    # Look at all items directly inside the directory, then keep only files.
    file_paths = sorted(
        Path(p) for p in glob.glob(os.path.join(str(directory), "*"))
        if Path(p).is_file()
    )

    for file_path in file_paths:
        try:
            text = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        results[file_path.name] = [m.group(0) for m in pattern.finditer(text)]

    return results
